    function setExportScope(scope) {
      if (currentTab === 'shop' && scope === 'day') {
        if (typeof showToast === 'function') {
          showToast("ℹ️ La Lista de Compras 3D se consolida únicamente por Semana Completa.");
        }
        return;
      }
      exportScope = scope;
      updateScopeUI();
    }

    function updateScopeUI() {
      const btnDay = document.getElementById('scope-btn-day');
      const btnWeek = document.getElementById('scope-btn-week');
      if (!btnDay || !btnWeek) return;

      const isShop = (currentTab === 'shop');
      
      if (isShop) {
        btnDay.style.opacity = '0.4';
        btnDay.style.cursor = 'not-allowed';
      } else {
        btnDay.style.opacity = '1';
        btnDay.style.cursor = 'pointer';
      }

      if (exportScope === 'day' && !isShop) {
        btnDay.style.background = 'var(--color-34plus)';
        btnDay.style.color = '#ffffff';
        btnDay.style.border = '1px solid var(--color-34plus)';
        
        btnWeek.style.background = 'var(--surface-card)';
        btnWeek.style.color = 'var(--text-main)';
        btnWeek.style.border = '1px solid var(--border-clinical)';
      } else {
        btnWeek.style.background = 'var(--color-34plus)';
        btnWeek.style.color = '#ffffff';
        btnWeek.style.border = '1px solid var(--color-34plus)';
        
        btnDay.style.background = 'var(--surface-card)';
        btnDay.style.color = 'var(--text-main)';
        btnDay.style.border = '1px solid var(--border-clinical)';
      }
    }

    function getActiveDayIdx() {
      if (typeof selectedIdx !== 'undefined') return selectedIdx;
      if (typeof window.selectedIdx !== 'undefined') return window.selectedIdx;
      return 0;
    }

    function buildMenuSummary(plan, scope, dayIdx, isWhatsApp) {
      let text = isWhatsApp 
        ? "📋 *DISEÑO PARAMÉTRICO DE MENÚS - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.split(' (')[0].toUpperCase()) + "*\n_Arquitectura Herami: Un Atelier T.I.L.O.®_\n\n"
        : "📋 DISEÑO PARAMÉTRICO OFICIAL DE MENÚS - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.toUpperCase()) + "\nArquitectura Herami: Un Atelier T.I.L.O.® — Transformación Inteligente y Logro Optimizado\n\n";

      const daysToIterate = scope === 'day' ? [plan.days[dayIdx]] : plan.days;
      daysToIterate.forEach((day, dIdx) => {
        if (!day) return;
        const actualIdx = scope === 'day' ? dayIdx : dIdx;
        text += isWhatsApp ? `📅 *${day.day.toUpperCase()} ${day.date_str.toUpperCase()}*\n` : `📅 ${day.day.toUpperCase()} ${day.date_str.toUpperCase()}\n`;
        (day.meals || []).forEach(rawM => {
          const m = getMealObj(actualIdx, rawM);
          const icon = m.meal_type.includes("Desayuno") ? "☀️" : (m.meal_type.includes("Comida") ? "🥗" : "🌙");
          const starter = resolveKetoDishAlias(m.starter_name || m.starter || m.entrada || "Entrada de la Granja");
          const main = resolveKetoDishAlias(m.main_dish_name || m.main_dish || m.main || m.principal || m.dish_name || "Plato Principal");
          const side = resolveKetoDishAlias(m.side_dish_name || m.side_dish || m.side || m.acompanamiento || "Acompañamiento de la Granja");

          if (isWhatsApp) {
            text += `${icon} *${m.meal_type}*: ${main}\n  └ _${starter}_ | _${side}_\n`;
          } else {
            text += `${icon} ${m.meal_type}:\n`;
            text += `  • Entrada: ${starter}\n`;
            text += `  • Plato Principal: ${main}\n`;
            text += `  • Acompañamiento: ${side}\n`;
          }
        });
        text += "\n";
      });
      return text;
    }

    function buildPrepSummaryDynamicSteps(plan, scope, dayIdx, isWhatsApp) {
      let text = isWhatsApp
        ? "👨‍🍳 *FICHAS DE ENSAMBLAJE (ATELIER HERAMI) - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.split(' (')[0].toUpperCase()) + "*\n_Arquitectura Herami: Un Atelier T.I.L.O.®_\n\n"
        : "👨‍🍳 FICHAS OFICIALES DE ENSAMBLAJE CULINARIO (ATELIER HERAMI) - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.toUpperCase()) + "\n\n";

      const daysToIterate = scope === 'day' ? [plan.days[dayIdx]] : plan.days;
      daysToIterate.forEach((day, dIdx) => {
        if (!day) return;
        const actualIdx = scope === 'day' ? dayIdx : dIdx;
        text += isWhatsApp ? `📅 *${day.day.toUpperCase()} ${day.date_str.toUpperCase()}*\n` : `📅 ${day.day.toUpperCase()} ${day.date_str.toUpperCase()}\n`;
        
        if (day.preliminary_preps && day.preliminary_preps.length > 0) {
          text += isWhatsApp ? "🥣 *Preps Previas*:\n" : "🥣 PREPARACIONES PREVIAS:\n";
          day.preliminary_preps.forEach(p => {
            text += `  • ${p.base_name}: ${p.cutting_prep} | ${p.cooking_process}\n`;
          });
          text += "\n";
        }

        (day.meals || []).forEach(rawM => {
          const m = getMealObj(actualIdx, rawM);
          const diners = getMealDiners(actualIdx, m.meal_type);
          const icon = m.meal_type.includes("Desayuno") ? "☀️" : (m.meal_type.includes("Comida") ? "🥗" : "🌙");
          const mainName = m.main_dish_name || m.main_dish || m.main || m.principal || m.dish_name || "Plato Principal";
          const mainPhases = (compiledPhasesCache[mainName] || compiledPhasesCache[resolveKetoDishAlias(mainName)]) || {
            f1: `Fase 1: Mise en Place para ${diners} personas.`,
            f2: `Fase 2: Acondicionamiento y porcionado.`,
            f3: `Fase 3: Cocción a fuego regulado.`,
            f4: `Fase 4: Emplatado a 65°C.`
          };
          const f1 = mainPhases.fase_1_mise_en_place || mainPhases.f1 || `Fase 1: Mise en Place para ${diners} personas.`;
          const f2 = mainPhases.fase_2_acondicionamiento || mainPhases.f2 || `Fase 2: Acondicionamiento.`;
          const f3 = mainPhases.fase_3_termodinamica || mainPhases.f3 || `Fase 3: Termodinámica.`;
          const f4 = mainPhases.fase_4_servicio || mainPhases.f4 || `Fase 4: Servicio.`;

          if (isWhatsApp) {
            text += `${icon} *${m.meal_type}* (${mainName}):\n`;
            text += `  └ 1. ${f1.slice(0, 75)}...\n`;
            text += `  └ 2. ${f3.slice(0, 75)}...\n`;
          } else {
            text += `${icon} ${m.meal_type} (${mainName}) - ${diners} pers:\n`;
            text += `  • F1 (Sazonado/Prep): ${f1}\n`;
            text += `  • F2 (Fuego/Término): ${f2}\n`;
            text += `  • F3 (Cocción/Sello): ${f3}\n`;
            text += `  • F4 (Emplatado/Servicio): ${f4}\n`;
          }
        });
        text += "\n";
      });
      return text;
    }

    function buildShopping3DSummary(plan, isWhatsApp) {
      const factor = activeDiners / 6.0;
      const farmList = [];
      const pantryList = [];
      const purchaseList = [];

      rawShopBase.forEach(item => {
        const isFarmCategory = item.category.includes('Cosecha');
        const isSelectedFarm = isFarmCategory && selectedHarvest.includes(item.item_name);
        const rawReq = (item.quantity || 1.0) * factor;
        const pStock = pantryStock[item.item_name] || 0.0;

        if (isSelectedFarm) {
          farmList.push(item.item_name);
        } else if (pStock >= rawReq) {
          pantryList.push(`${item.item_name} (${pStock} ${item.unit || ''})`);
        } else {
          const netQty = (rawReq - pStock).toFixed(1).replace('.0', '');
          const unitMatch = item.unit || '';
          purchaseList.push(`${item.item_name}: ${netQty} ${unitMatch}`);
        }
      });

      let text = isWhatsApp 
        ? "🛒 *LISTA DE COMPRAS TRIDIMENSIONAL - " + activeWeek.split(' (')[0].toUpperCase() + "*\n_Calculada para " + activeDiners + " comensales_\n\n"
        : "🛒 LISTA DE COMPRAS TRIDIMENSIONAL CONSOLIDADA - " + activeWeek.toUpperCase() + "\nCalculada dinámicamente para " + activeDiners + " comensales\n\n";

      text += isWhatsApp ? "🛍️ *COMPRAS NETAS SUPERMERCADO*:\n" : "🛒 COMPRAS NETAS A ADQUIRIR EN SUPERMERCADO:\n";
      if (purchaseList.length === 0) text += "  • ¡Todo cubierto por cosecha y alacena!\n";
      else purchaseList.forEach(i => text += `  • ${i}\n`);
      text += "\n";

      if (farmList.length > 0) {
        text += isWhatsApp ? "🌾 *COSECHA GRANJA ($0)*:\n" : "🌾 COSECHA DIRECTA DE LA GRANJA EL HERAMI (SUMINISTRO PROPIO $0):\n";
        farmList.forEach(i => text += `  • ${i}\n`);
        text += "\n";
      }

      if (pantryList.length > 0) {
        text += isWhatsApp ? "🧊 *STOCK ALACENA*:\n" : "🧊 CUBIERTO POR STOCK DE ALACENA Y REFRIGERADOR:\n";
        pantryList.forEach(i => text += `  • ${i}\n`);
        text += "\n";
      }

      return text;
    }

    function buildNutritionalSinergixSummary(plan, scope, dayIdx, isWhatsApp) {
      let text = isWhatsApp
        ? "📊 *REPORTE NUTRICIONAL & SINERGIX - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.split(' (')[0].toUpperCase()) + "*\n_Ecosistema T.I.L.O.® / " + activeDiners + " comensales_\n\n"
        : "📊 REPORTE NUTRICIONAL Y CRONOGRAMA SINERGIX - " + (scope === 'day' ? (plan.days[dayIdx]?.day.toUpperCase() + " " + plan.days[dayIdx]?.date_str.toUpperCase()) : activeWeek.toUpperCase()) + "\n\n";

      text += isWhatsApp ? "💊 *CRONOGRAMA SINERGIX (4 TOMAS)*:\n" : "💊 CRONOGRAMA DE SUPLEMENTACIÓN SINERGIX (4 TOMAS DIARIAS - 1 DOSIS COMPLETA):\n";
      text += "  • ☀️ TOMA 1 (Al Despertar): Multi Sinergix (CoQ10/PQQ ayunas)\n";
      text += "  • 🍳 TOMA 2 (Desayuno): Multi Sinergix (Soporte enzimático)\n";
      text += "  • 🥗 TOMA 3 (Cena): Amino Sinergix (Péptidos y electrolitos)\n";
      text += "  • 🌙 TOMA 4 (Al Dormir): Amino Sinergix (Cross-linking & Mg)\n\n";

      const daysToIterate = scope === 'day' ? [plan.days[dayIdx]] : plan.days;
      daysToIterate.forEach((day, dIdx) => {
        if (!day) return;
        const actualIdx = scope === 'day' ? dayIdx : dIdx;
        text += isWhatsApp ? `📅 *${day.day.toUpperCase()} ${day.date_str.toUpperCase()}*\n` : `📅 ${day.day.toUpperCase()} ${day.date_str.toUpperCase()}\n`;
        (day.meals || []).forEach(rawM => {
          const m = getMealObj(actualIdx, rawM);
          const diners = getMealDiners(actualIdx, m.meal_type);
          const factor = diners / 6.0;
          const kcal = ((m.fat_g * 9 + m.protein_g * 4 + m.net_carbs_g * 4) * factor).toFixed(0);
          const mainName = m.main_dish_name || m.main_dish || m.main || m.principal || m.dish_name || "Plato Principal";

          text += `  • ${m.meal_type} (${mainName}): 🔥 ${kcal} kcal | 🧈 Fat ${(m.fat_g * factor).toFixed(1)}g | 🥩 Prot ${(m.protein_g * factor).toFixed(1)}g | 🥑 Carbs ${(m.net_carbs_g * factor).toFixed(1)}g\n`;
        });
        text += "\n";
      });
      return text;
    }

    function buildContextualExportText(tab, scope, dayIdx, isWhatsApp) {
      const plan = datasets[activeWeek] || datasets["Semana 34 (16 al 22 de Agosto de 2026)"] || datasets["Semana 33 (09 al 15 de Agosto de 2026)"];
      if (!plan) return "Error: Datos de plan no disponibles.";

      switch (tab) {
        case 'menu': return buildMenuSummary(plan, scope, dayIdx, isWhatsApp);
        case 'prep': return buildPrepSummaryDynamicSteps(plan, scope, dayIdx, isWhatsApp);
        case 'shop': return buildShopping3DSummary(plan, isWhatsApp);
        case 'nutri': return buildNutritionalSinergixSummary(plan, scope, dayIdx, isWhatsApp);
        default: return buildMenuSummary(plan, scope, dayIdx, isWhatsApp);
      }
    }

    function exportViaWhatsApp() {
      const dayIdx = getActiveDayIdx();
      const text = buildContextualExportText(currentTab, exportScope, dayIdx, true);
      const encodedText = encodeURIComponent(text);
      const waUrl = `https://api.whatsapp.com/send?text=${encodedText}`;
      
      closeExportSummaryModal();

      if (/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
        window.location.href = waUrl;
      } else {
        window.open(waUrl, '_blank');
      }
    }

    function exportViaDownloadTxt() {
      const dayIdx = getActiveDayIdx();
      const fullText = buildContextualExportText(currentTab, exportScope, dayIdx, false);
      const blob = new Blob([fullText], { type: 'text/plain;charset=utf-8' });
      const url = URL.createObjectURL(blob);

      const safeWeekName = (typeof activeWeek !== 'undefined' && activeWeek) 
        ? activeWeek.replace(/[^a-zA-Z0-9]/g, '_') 
        : 'Semana_Actual';

      const a = document.createElement('a');
      a.href = url;
      a.download = `Reporte_${currentTab.toUpperCase()}_${safeWeekName}.txt`;

      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      closeExportSummaryModal();
    }

    function exportViaClipboard() {
      const dayIdx = getActiveDayIdx();
      const fullText = buildContextualExportText(currentTab, exportScope, dayIdx, false);
      copyToClipboardRobust(fullText);
      closeExportSummaryModal();
    }

    function copyToClipboardRobust(text) {
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(() => {
          showToast("📋 ¡Resumen copiado al portapapeles!");
        }).catch(() => {
          fallbackCopyText(text);
        });
      } else {
        fallbackCopyText(text);
      }
    }

    function fallbackCopyText(text) {
      const textArea = document.createElement("textarea");
      textArea.value = text;
      textArea.style.position = "fixed";
      textArea.style.top = "0";
      textArea.style.left = "-9999px";
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      try {
        const successful = document.execCommand('copy');
        if (successful) showToast("📋 ¡Resumen copiado al portapapeles!");
        else showToast("⚠️ No se pudo copiar automáticamente.");
      } catch (err) {
        console.error("Error en fallback de copia:", err);
      }
      document.body.removeChild(textArea);
    }

    function showToast(msg) {
      let toast = document.getElementById('app-toast-notif');
      if (!toast) {
        toast = document.createElement('div');
        toast.id = 'app-toast-notif';
        toast.style.cssText = 'position:fixed; bottom:24px; right:24px; background:var(--color-navy); color:#fff; padding:12px 20px; border-radius:12px; border:1px solid var(--color-34plus); font-weight:700; font-size:0.88rem; z-index:99999; box-shadow:0 10px 25px rgba(0,0,0,0.3); transition:all 0.3s ease;';
        document.body.appendChild(toast);
      }
      toast.innerText = msg;
      toast.style.display = 'block';
      setTimeout(() => { toast.style.display = 'none'; }, 3500);
    }

    function updateIntakeDatalist() {
      const dataList = document.getElementById('existing-items-list');
      const catSelect = document.getElementById('intake-category');
      if (!dataList) return;
      dataList.innerHTML = '';
      
      const selCat = catSelect ? catSelect.value : '';
      rawShopBase.forEach(item => {
        const itemCat = getSmartItemCategory(item.item_name, item.category);
        if (!selCat || itemCat === selCat || selCat.includes('Cosecha')) {
          const opt = document.createElement('option');
          opt.value = item.item_name;
          dataList.appendChild(opt);
        }
      });
    }

    function onIntakeSourceChange(val) {
      const catSelect = document.getElementById('intake-category');
      const destSelect = document.getElementById('intake-storage-dest');
      if (val.includes('Cosecha')) {
        if (catSelect) catSelect.value = '🌾 Cosecha Directa de la Granja / Huerto';
        if (destSelect) destSelect.value = '🌿 Mesa de Trabajo / Preparación Inmediata';
      } else if (val.includes('Proveedor')) {
        if (destSelect) destSelect.value = '🏺 Alacena Principal / Seca';
      }
      updateIntakeDatalist();
    }

    function openInventoryIntakeModal() {
      const todayStr = new Date().toISOString().split('T')[0];
      const dateInput = document.getElementById('intake-date');
      if (dateInput) dateInput.value = todayStr;

      document.getElementById('intake-item-name').value = '';
      document.getElementById('intake-quantity').value = '1.0';
      document.getElementById('intake-batch-notes').value = '';

      updateIntakeDatalist();
      document.getElementById('inventory-entry-modal').style.display = 'flex';
    }

    function closeInventoryIntakeModal() {
      document.getElementById('inventory-entry-modal').style.display = 'none';
    }

    async function submitInventoryIntake(btnEl) {
      const sourceTypeSelect = document.getElementById('intake-source-type');
      const nameInput = document.getElementById('intake-item-name');
      const qtyInput = document.getElementById('intake-quantity');
      const unitSelect = document.getElementById('intake-unit');
      const catSelect = document.getElementById('intake-category');
      const storageDestSelect = document.getElementById('intake-storage-dest');
      const dateInput = document.getElementById('intake-date');
      const notesInput = document.getElementById('intake-batch-notes');

      const sourceType = sourceTypeSelect ? sourceTypeSelect.value : '🛒 Supermercado / Compra Neta';
      const valName = nameInput.value.trim();
      const qty = parseFloat(qtyInput.value) || 0;
      const unit = unitSelect.value;
      const cat = catSelect.value;
      const storageDest = storageDestSelect ? storageDestSelect.value : '🏺 Alacena Principal / Seca';
      const intakeDate = dateInput ? dateInput.value : '';
      const batchNotes = notesInput ? notesInput.value.trim() : '';

      if (!valName || qty <= 0) {
        showToast("⚠️ Ingresa un nombre válido y cantidad mayor a 0.");
        return;
      }

      if (btnEl) {
        btnEl.disabled = true;
        btnEl.style.opacity = '0.7';
        btnEl.innerText = '📦 Consolidando...';
      }

      const smartCat = getSmartItemCategory(valName, cat);

      const existingInShop = rawShopBase.find(i => i.item_name.toLowerCase() === valName.toLowerCase());
      if (existingInShop) {
        existingInShop.category = smartCat;
      } else {
        rawShopBase.push({
          id: 400 + rawShopBase.length + 1,
          category: smartCat,
          item_name: valName,
          quantity: qty,
          unit: unit,
          quantity_str: `${qty} ${unit}`
        });
      }

      if (sourceType.includes('Cosecha') || cat.includes('Cosecha')) {
        if (!selectedHarvest.includes(valName)) selectedHarvest.push(valName);
      } else {
        const currentPantry = pantryStock[valName] || 0.0;
        pantryStock[valName] = currentPantry + qty;
      }

      saveAppState();
      initSetupPanel();
      render3DShoppingList();

      try {
        await fetch('/api/inventory/intake', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            source_type: sourceType,
            item_name: valName,
            quantity: qty,
            unit: unit,
            category: smartCat,
            storage_destination: storageDest,
            intake_date: intakeDate,
            batch_notes: batchNotes
          })
        });
      } catch (e) {
        console.error("Notificación API intake:", e);
      } finally {
        if (btnEl) {
          btnEl.disabled = false;
          btnEl.style.opacity = '1';
          btnEl.innerText = '📦 Consolidar Abastecimiento';
        }
        closeInventoryIntakeModal();
        showToast(`📦 ¡Abastecimiento consolidado! +${qty} ${unit} de '${valName}' en ${storageDest.split(' / ')[0]}.`);
      }
    }

    // Inicialización al cargar la aplicación: Cargar inventario registrado y desplegar pantalla de inicio
    loadAppState();
    initSetupPanel();

    // La Fase Previa se muestra como pantalla de inicio con el inventario recuperado y los botones de acción inmediata
    document.getElementById('setup-overlay').style.display = 'block';
    document.getElementById('main-app-content').style.display = 'none';
  